    "alert_id": "P005_TDF_RENAL_001",
    "title": "TDF contraindicated in kidney disease",
    "message": "Guidelines state TDF is contraindicated in kidney disease with eGFR below 60 ml/min. Patient's eGFR is 52 mL/min/1.73m2, placing them in this category. TDF is a known cause of chronic kidney disease, and creatinine has risen steadily from 0.9 to 1.4 mg/dL over 6 years on TDF, supporting drug attribution. However, proteinuria (1+) suggests possible intrinsic renal disease, and regular ibuprofen use is a non-drug risk factor for kidney injury.",
    "issue_type": "medication_safety",
    "severity": "critical",
    "recommended_action": "Discontinue TDF and switch to a TDF-sparing ART regimen as per guidelines for eGFR <60 ml/min.",
    "citations": [
      {"page_number": 6, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__s9_c2"},
      {"page_number": 37, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__s27_c6"}
    ]
  },
  {
    "alert_id": "P005_MONITORING_GAP_001",
    "title": "Missing annual renal monitoring on TDF",
    "message": "Guidelines require serum creatinine and eGFR monitoring every 12 months for experienced patients on TDF. The patient is on TDF, but there is no evidence this annual monitoring was performed or planned. The rising creatinine trend underscores the need for regular monitoring.",
    "issue_type": "monitoring_gap",
    "severity": "high",
    "recommended_action": "Order serum creatinine and eGFR now and ensure they are performed every 12 months while on TDF.",
    "citations": [
      {"page_number": 29, "chunk_id": "hiv_guidelines_art.extraction__hiv_guidelines_art.extraction__s24_c19"}
    ]
  },
  {
    "alert_id": "P005_DM_SCREEN_001",
    "title": "Missing diabetes screening for DTG",
    "message": "Guidelines require screening for hyperglycaemia risk factors before initiating or transitioning to DTG. The patient is on DTG and has risk factors: age ≥30 years and proteinuria with trace glucose. There is no record of glucose screening or a plan for glucose monitoring every 3 months for the first year on DTG as required.",
    "issue_type": "monitoring_gap",
    "severity": "moderate",
    "recommended_action": "Check blood glucose now. If high, do not continue DTG. If normal, initiate glucose monitoring every 3 months for the first year on DTG.",
    "citations": [
      {"page_number": 189, "chunk_id": "hiv_guidelines_co_infectionscreening.extraction__hiv_guidelines_co_infectionscreening.extraction__p38_c2"},
      {"page_number": 38, "chunk_id": "hiv_guidelines_co_infectionscreening.extraction__hiv_guidelines_co_infectionscreening.extraction__s24_c11"}
    ]
  },
