    "alert_id": "P005_NSAID_RISK_001",
    "title": "Ibuprofen use with renal impairment",
    "message": "Patient has chronic kidney disease (eGFR 52) and uses ibuprofen 2-3 times weekly. NSAIDs are nephrotoxic, especially in pre-existing renal impairment. This compounds the renal risk from TDF. Fatigue, a reported symptom, can also be a sign of kidney disease progression.",
    "issue_type": "drug_interaction",
    "severity": "high",
    "recommended_action": "Advise to discontinue ibuprofen immediately. Recommend alternative analgesia (e.g., paracetamol) and counsel on NSAID risks in CKD.",
    "citations": []
  }
]

